        <div className="flex items-start justify-between gap-4 border-b border-slate-200 px-5 py-4">
          <h2 id={HEADING_ID} className="min-w-0 break-words text-lg font-semibold text-slate-900">
            {invoice ? `Invoice ${invoice.id}` : "Invoice not found"}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="shrink-0 rounded-md px-3 py-1.5 text-sm font-medium text-slate-500 hover:bg-slate-100"
