                        <span className="ml-3 text-xs capitalize text-slate-500">{followUp.channel}</span>
                        <p className="mt-1 break-words">{followUp.note}</p>
                      </li>
                    ))}
                  </ul>
                );
              })()}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}


