  const m = Number(match[2]);
  const d = Number(match[3]);
  if (m < 1 || m > 12 || d < 1) return null;
  if (d > daysInMonth(y, m - 1)) return null;
  return { y, m, d };
}

/** True only for a real calendar date in strict "YYYY-MM-DD" form (rejects e.g. 2026-02-30). */
export function isValidIsoDate(date: string): boolean {
  return parseIso(date) !== null;
}

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, monthIndex0: number): number {
  const days = [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return days[monthIndex0];
}

function pad(n: number, width: number): string {
  return String(n).padStart(width, "0");
}

function formatIso(y: number, m0: number, d: number): string {
  return `${pad(y, 4)}-${pad(m0 + 1, 2)}-${pad(d, 2)}`;
}

