      return {
        ...state,
        bills: result.state.bills,
        billPayments: result.state.billPayments,
        cashAccounts: result.state.cashAccounts,
      };
    }

    case "reset":
      return createInitialState(state.resetCount + 1);

    default:
      return state;
  }
}

